// Adapted from Zard UI 1.1.1 (MIT) — https://github.com/zard-ui/zardui
import { ChangeDetectionStrategy, Component, computed, Directive, input } from "@angular/core";
import { cn } from "@/ui/utils";

/** A dense table inside an `overflow-x-auto` wrapper, so a wide table scrolls instead of clipping. */
@Component({
  selector: "ko-table",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "block" },
  template: `<div class="w-full overflow-x-auto">
    <table class="w-full text-left text-sm">
      <ng-content />
    </table>
  </div>`,
})
export class KoTable {}

@Directive({ selector: "thead[koTableHeader]", host: { "[class]": "classes()" } })
export class KoTableHeader {
  readonly class = input<string>("");
  protected readonly classes = computed(() => cn("text-xs text-muted-foreground", this.class()));
}

@Directive({ selector: "tbody[koTableBody]", host: { "[class]": "classes()" } })
export class KoTableBody {
  readonly class = input<string>("");
  protected readonly classes = computed(() => cn(this.class()));
}

@Directive({ selector: "tr[koTableRow]", host: { "[class]": "classes()" } })
export class KoTableRow {
  readonly class = input<string>("");
  protected readonly classes = computed(() =>
    cn(
      "group transition-colors [tbody_&]:border-t [tbody_&]:border-border [tbody_&]:hover:bg-secondary/30",
      this.class(),
    ),
  );
}

@Directive({ selector: "th[koTableHead]", host: { "[class]": "classes()" } })
export class KoTableHead {
  readonly class = input<string>("");
  protected readonly classes = computed(() => cn("px-4 py-3 font-normal", this.class()));
}

@Directive({ selector: "td[koTableCell]", host: { "[class]": "classes()" } })
export class KoTableCell {
  readonly class = input<string>("");
  protected readonly classes = computed(() => cn("h-12 px-4 py-2", this.class()));
}

import { ChangeDetectionStrategy, Component, provideZonelessChangeDetection } from "@angular/core";
import { TestBed } from "@angular/core/testing";
import {
  KoTable,
  KoTableBody,
  KoTableCell,
  KoTableHead,
  KoTableHeader,
  KoTableRow,
} from "@/ui/primitives/table.component";

@Component({
  selector: "ko-table-host",
  imports: [KoTable, KoTableHeader, KoTableBody, KoTableRow, KoTableHead, KoTableCell],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <ko-table class="mt-4">
      <thead koTableHeader>
        <tr koTableRow>
          <th koTableHead>Name</th>
        </tr>
      </thead>
      <tbody koTableBody>
        <tr koTableRow>
          <td koTableCell>Alpha</td>
        </tr>
      </tbody>
    </ko-table>
  `,
})
class HostComponent {}

describe("KoTable", () => {
  let root: HTMLElement;

  beforeEach(async () => {
    TestBed.configureTestingModule({ providers: [provideZonelessChangeDetection()] });
    const fixture = TestBed.createComponent(HostComponent);
    await fixture.whenStable();
    root = fixture.nativeElement as HTMLElement;
  });

  it("wraps the table in an overflow-x-auto div", () => {
    const wrapper = root.querySelector("ko-table > div")!;
    expect(wrapper.classList.contains("overflow-x-auto")).toBe(true);
    expect(wrapper.classList.contains("w-full")).toBe(true);
    expect(wrapper.querySelector(":scope > table")).not.toBeNull();
  });

  it("keeps a consumer class on the host and the fixed classes on the table", () => {
    expect(root.querySelector("ko-table")!.classList.contains("mt-4")).toBe(true);
    const table = root.querySelector("table")!;
    expect(table.classList.contains("mt-4")).toBe(false);
    for (const name of ["w-full", "text-left", "text-sm"]) {
      expect(table.classList.contains(name)).toBe(true);
    }
  });

  it("projects thead and tbody inside the table", () => {
    const table = root.querySelector("table")!;
    expect(table.querySelector(":scope > thead th")?.textContent).toBe("Name");
    expect(table.querySelector(":scope > tbody td")?.textContent).toBe("Alpha");
  });

  it("is a block host", () => {
    expect(root.querySelector("ko-table")!.classList.contains("block")).toBe(true);
  });
});
